#!/usr/bin/env node
/**
 * Icecast simulator for radio e2e — a real ICY server, no network needed.
 *
 * Serves a looped MP3 (given as argv[2], or generated by radio.check.sh) at a
 * realistic 128kbps pace on every path, negotiating ICY exactly like Icecast:
 *   - icy-name / icy-genre / icy-url / icy-br headers
 *   - when the client sends `Icy-MetaData: 1`, audio is interleaved with a
 *     metadata block every icy-metaint bytes carrying StreamTitle/StreamUrl
 * The now-playing title rotates every ROTATE_SEC through a playlist that mixes
 * songs ("Artist - Title"), adverts, blank ad-break titles and DJ/news talk, so
 * the capture + classifier path can be asserted deterministically.
 *
 *   node icecast-sim.js <port> <loop.mp3> [rotateSec]
 */
const http = require('node:http');
const fs = require('node:fs');

const PORT = parseInt(process.argv[2] || '9155', 10);
const MP3 = process.argv[3] || '/tmp/radio_loop.mp3';
const ROTATE_SEC = parseFloat(process.argv[4] || '8');
const METAINT = 4096;
const BYTES_PER_SEC = 16000; // 128 kbps

const PLAYLIST = [
  { title: 'Aurora Skies - Neon Rain', url: 'https://sim.example/art/neon.jpg' },      // song
  { title: 'Advert: Crunchy Cola refreshes best', url: '' },                            // ad
  { title: 'The Midnight Owls - Paper Boats', url: 'https://sim.example/art/owls.jpg' },// song
  { title: 'News bulletin with Dana Reeves', url: '' },                                 // content
  { title: '', url: '' },                                                               // ad break (blank)
  { title: 'DJ Max morning show - your calls', url: '' },                               // content
];
let idx = 0;
let current = PLAYLIST[0];
setInterval(() => { idx = (idx + 1) % PLAYLIST.length; current = PLAYLIST[idx]; }, ROTATE_SEC * 1000);

const audio = fs.readFileSync(MP3);
if (!audio.length) { console.error('empty loop mp3'); process.exit(1); }

function icyBlock() {
  const text = `StreamTitle='${current.title.replace(/'/g, ' ')}';StreamUrl='${current.url}';`;
  const pad = Math.ceil(text.length / 16);
  const buf = Buffer.alloc(1 + pad * 16);
  buf[0] = pad;
  buf.write(text, 1, 'utf8');
  return buf;
}

const server = http.createServer((req, res) => {
  const wantsMeta = String(req.headers['icy-metadata'] || '') === '1';
  res.writeHead(200, {
    'Content-Type': 'audio/mpeg',
    'icy-name': 'Sim FM',
    'icy-genre': 'Test Tones',
    'icy-url': 'https://sim.example',
    'icy-br': '128',
    ...(wantsMeta ? { 'icy-metaint': String(METAINT) } : {}),
    'Cache-Control': 'no-cache',
  });
  let pos = 0;          // position in the loop
  let countdown = METAINT;
  let lastSent = null;  // dedupe metadata per client (like Icecast: empty block when unchanged)
  const timer = setInterval(() => {
    let budget = BYTES_PER_SEC / 4; // 250ms pace
    while (budget > 0) {
      const take = Math.min(budget, wantsMeta ? countdown : budget, audio.length - pos);
      if (take > 0) {
        res.write(audio.subarray(pos, pos + take));
        pos = (pos + take) % audio.length;
        budget -= take;
        if (wantsMeta) countdown -= take;
      }
      if (wantsMeta && countdown === 0) {
        if (lastSent !== current.title) { res.write(icyBlock()); lastSent = current.title; }
        else res.write(Buffer.from([0]));
        countdown = METAINT;
      }
      if (take === 0 && !(wantsMeta && countdown === 0)) break;
    }
  }, 250);
  req.on('close', () => clearInterval(timer));
  res.on('error', () => clearInterval(timer));
});
server.listen(PORT, () => console.log(`icecast-sim on :${PORT} (rotate ${ROTATE_SEC}s, metaint ${METAINT})`));
